    springsCurrentLength: "and current length ℓ",
    springsEnergy: ", and the energy is",
    springsModelViewer: "(Eq. 3). The viewer shows axial force on the deformed truss. We compute the following responses.",
    springsStripTest: "Linear strip test.",
    springsStripMethod: "A 13 × 52 strip with {nodes} nodes, compared with the paper’s approximately 676 vertices (Sec. V A, pp. 9–10). We hold complete end rows selected before disorder and prescribe a vertical increment ε × 52; the paper sets the top vertices to y = 52(1 + ε). These are different boundary prescriptions. Width is measured between the nodes nearest mid-height. The production truss solver agrees below 10⁻¹³ (recorded; tolerance 10⁻⁸).",
    springsExactModuli: "Exact effective moduli.",
    springsPeriodicMethod: "A periodic cell under an imposed macroscopic strain, with every node free to relax: the stiffness that remains is the network’s elastic tensor C, including the nonaffine softening, with no boundary effects. The uniform-strain (affine) tensor is the same sum without relaxation.",
    springsPrestress: "Prestress",
    springsPrestressMethod: "(an addition, not in the paper’s computations): rest lengths shortened by a fraction, the network relaxed to equilibrium by Newton’s method, and the linear response taken about that state, tension stiffening included.",
    springsComparison: "Comparison with the paper",
    springsFoamHeading: "Foam: the auxetic transition",
    springsFoamComparison: "The periodic directional ν along y uses {seeds} seeds of {cells} × {cells} cells, crosses zero at η = {cross}, and reaches {last} at η = 0.5 ({near} at 0.49). The paper reports approximately 0.46 and −0.1. This cross-protocol comparison falls within all ten upward Fig. 5 error bars plus 0.003 digitisation; it does not validate the strip. Fig. 5 reports ten realizations; our seeds are our own choice.",
