    ferrariNumbers: "Con {elements} elementi per asta, |λ₁ − {reference}| = {error}, sotto la tolleranza di {tolerance}. La massima discrepanza scalata delle derivate è {derivative}, sotto {derivativeTolerance}. Sono verifiche del solo sottoinsieme implementato.",
