    ferrariScope: "Cosa viene riprodotto",
    ferrariScopeText: "Questa prima versione verifica il carico critico del telaio semplice del §2.1.2, con il motore di produzione. Traccia anche un percorso imperfetto con il solutore corotazionale a lunghezza d’arco di produzione. Il percorso non è una riproduzione validata della Figura 2b.",
    ferrariModel: "Due aste di {length} m, incernierate agli estremi esterni e unite rigidamente nell’angolo. E = {young} MPa, A = {area} m², J = {inertia} m⁴. Un carico di riferimento di {force} kN verso il basso agisce nell’angolo. Il percorso aggiunge un momento di riferimento di +{moment} kN·m; ci sono {elements} elementi per asta.",
    ferrariEvidence: "Evidenze e limiti",
    ferrariEvidenceText: "Il carico di instabilità lineare di produzione è confrontato con l’articolo. Ogni derivata parziale dell’energia di un elemento verticale fino all’ordine quattro è verificata con differenze centrali in tre stati. Queste verifiche validano le derivate dell’energia della trave in stile produzione; non validano i coefficienti di Koiter.",
    ferrariMissing: "I risultati calcolati coprono l’instabilità lineare e un percorso con carico eccentrico. Gli α e β elencati sono solo trascrizioni dell’articolo. Ottimizzazione, modi multipli, assemblaggi più grandi e validazione sperimentale sono fuori da questo confronto.",
    ferrariBlocker: "Uno spostamento lineare scalato e un modo di instabilità lineare non soddisfano le equazioni non lineari del punto critico nella sonda iniziale. Da quel calcolo respinto non viene mostrato alcun coefficiente né previsione di Koiter. Occorre prima risolvere lo stato critico e la normalizzazione modale.",
