    ferrariComparison: "Ogni campione del percorso salvato è verificato rispetto a un calcolo nativo di produzione. Il solutore nel browser è verificato rispetto a spostamento finale, rotazione e moltiplicatore del carico nativi. Questa è una regressione del solutore, non un confronto con il codice degli autori né con la Figura 2b.",
    formPositionError: "Errore massimo di posizione rispetto al riferimento",
    formForceError: "Errore massimo di forza rispetto al riferimento",
    formTitle: "Quattro cavi, un equilibrio",
    formLead: "Trova la forma del sistema a quattro aste della Fig. 2 usando densità di forza positive. Cambia il carico, ricalcola in Rust, poi apri la geometria trovata come travatura reticolare in Stabileo.",
    formScopeTitle: "Cosa viene riprodotto",
    formScope: "Questa prima versione implementa il problema diretto di equilibrio della Sezione 2.1, Fig. 2 ed Eq. (7). La nostra rete a quattro cavi ha un nodo libero e quattro vincoli fissi. La sua topologia segue l’articolo; le sue dimensioni e i suoi carichi sono scelti qui in modo esplicito, non trascritti dalla figura. L’articolo sviluppa il progetto inverso differenziabile; quel contributo è fuori da questa versione.",
    formMethodTitle: "Il metodo diretto",
    formMethod: "La densità di forza è la tensione assiale divisa per la lunghezza dell’asta. Densità positive danno a una rete ancorata una matrice di equilibrio definita positiva. Il crate di ricerca assembla questa matrice e usa la fattorizzazione di Cholesky sparsa del motore di produzione per le tre coordinate. Le forze seguono da f = qℓ.",
    formInputs: "I vincoli sono in (±2, ±2, 0) m. Il carico di base verso il basso è 4 kN e ogni densità è 1 kN/m. L’Eq. (7) dà allora z = −1 m, lunghezza = 3 m e tensione = 3 kN. Sono obiettivi derivati per i nostri input, non osservazioni numeriche pubblicate.",
    formEvidenceTitle: "Evidenze e tolleranze",
    formCheckLabel: "Rispetto a jax_fdm (10 verifiche); 20 verifiche analitiche/del motore qui sotto",
    formComparison: "I nostri input: confrontati con l’Eq. (7) e jax_fdm; i risultati numerici dell’articolo non sono riprodotti.",
    formDensityHint: "Inserisci 0.5–2 kN/m.",
    formLoadHint: "Inserisci 1–8 kN.",
    researchLanguages: "I contenuti di ricerca sono disponibili in inglese, spagnolo, portoghese, ungherese, italiano, cinese semplificato e neerlandese. Le traduzioni disponibili variano secondo il benchmark. Se manca una traduzione viene visualizzato il testo inglese.",
    formEvidence: "Cinque casi di input confrontano ogni coordinata e forza nei cavi con jax_fdm non modificato in float64. Le tolleranze assolute sono 1e-12 m per le coordinate, 1e-12 kN per le forze di riferimento e i residui di equilibrio, e 1e-9 kN per le forze di produzione nella travatura reticolare. Il file di validazione registra ogni errore osservato. La riproduzione è una scansione di carico calcolata dallo stesso solutore Rust, non iterazioni di convergenza. Le scale sono circa 3 m, 3–12 kN ed EA = 200000 kN. Il margine di 1e-12 consente gli errori di arrotondamento dell’assemblaggio e di Cholesky in float64; 1e-9 kN consente la cancellazione nel recuperare le forze elastiche da piccoli spostamenti con questa grande rigidezza.",
    formReference: "Riferimento: jax_fdm, MIT, revisione 9a17fd379071fb3511ca914f46e8d1e8c286460e. Il manifesto registra lo SHA-256 dell’archivio sorgente, gli hash dell’output e l’ambiente installato. Questa revisione non è stata confermata come la revisione della pubblicazione.",
    formEngineTitle: "Cosa verifica il motore di produzione",
    formEngine: "L’editor riceve la geometria trovata, le traslazioni dei vincoli fissi e lo stesso carico verticale come una travatura reticolare 3D elastica lineare. Con rigidezze uguali delle aste, la simmetria fa coincidere i suoi sforzi normali con quelli del FDM. I test verificano anche il suo spostamento verticale rispetto alla forma chiusa elastica. È un’analisi separata con carico verticale applicato ad aste inizialmente prive di pretensione: la pretensione dei cavi e la rigidezza geometrica non vengono trasferite.",
    formLimitsTitle: "Non ancora riprodotto",
    formLimits: "Nessun metodo dell’aggiunto, gradiente, ottimizzazione, guscio, trazione/compressione miste, carico dipendente dalla forma, instabilità o affermazione sui tempi. Non si riproducono forme ottimizzate né valori di tabella pubblicati. L’anteprima è una proiezione etichettata; l’editor contiene il modello spaziale completo.",
    formDisclaimer: "La concordanza con un altro codice non è validazione sperimentale né certificazione ingegneristica.",
