    springsEditorFailed: "Non è stato possibile caricare l’editor di Stabileo:",

    springsTitle: "Reti di molle auxetiche",
    springsLead: "Tira una striscia di molle hookeane e leggi quanto si restringe. Scuoti i nodi del reticolo triangolare e inizia invece ad allargarsi: diventa auxetica. La rete a destra viene risolta nel tuo browser come una travatura reticolare sul motore di Stabileo, e la stessa striscia si apre nel vero editor di Stabileo. Nessun codice di riferimento è pubblico (“disponibile su richiesta”), quindi confrontiamo con i numeri, le forme chiuse e le figure pubblicati nell’articolo e con risultati esatti.",
    springsPaperShows: "Cosa mostra l’articolo",
    springsOverview: "Molti materiali, dai reticoli metamateriali alle membrane cellulari, sono modellati come reti di molle hookeane. Grossman e Boudaoud ricavano il continuo elastico a cui una tale rete si comporta in modo equivalente, usando solo la sua geometria e la sua topologia, e ne calcolano gli",
    springsNonaffine: "spostamenti non affini",
    springsOverviewRelaxation: "cioè le deviazioni locali da un allungamento uniforme che rendono le reti disordinate più morbide della stima a deformazione uniforme. Verificano la teoria con simulazioni di una striscia tesa per tre famiglie: reticoli triangolari ordinati, un nido d’ape che diventa rientrante e una “schiuma” ottenuta spostando a caso i nodi di un reticolo triangolare, che diventa",
    springsAuxetic: "auxetica",
    springsOverviewAuxetic: "(coefficiente di Poisson negativo: si allarga quando viene tirata) al crescere del disordine.",
    springsTry: "Provalo:",
    springsPerfect: "reticolo perfetto, η = 0",
    springsTryAuxetic: "η = 0.5, auxetico",
    springsModel: "Il modello che risolviamo",
    springsSprings: "Le molle",
    springsJoin: "collegano i nodi; ognuna ha rigidezza",
    springsRestLength: ", lunghezza a riposo ℓ̄",
    springsCurrentLength: "e lunghezza attuale ℓ",
    springsEnergy: ", e l’energia è",
    springsModelViewer: "(Eq. 3). Il visualizzatore mostra lo sforzo normale sulla travatura deformata. Calcoliamo le risposte seguenti.",
    springsStripTest: "Prova lineare sulla striscia.",
    springsStripMethod: "Una striscia 13 × 52 con {nodes} nodi, confrontata con i circa 676 vertici dell’articolo (Sez. V A, pp. 9–10). Teniamo bloccate le righe di estremità complete scelte prima del disordine e imponiamo un incremento verticale ε × 52; l’articolo imposta i vertici superiori a y = 52(1 + ε). Sono prescrizioni al contorno diverse. La larghezza è misurata tra i nodi più vicini a metà altezza. Il solutore di produzione per la travatura concorda sotto 10⁻¹³ (registrato; tolleranza 10⁻⁸).",
    springsExactModuli: "Moduli efficaci esatti.",
    springsPeriodicMethod: "Una cella periodica sotto una deformazione macroscopica imposta, con ogni nodo libero di rilassarsi: la rigidezza che resta è il tensore elastico C della rete, compreso l’ammorbidimento non affine, senza effetti di contorno. Il tensore a deformazione uniforme (affine) è la stessa somma senza rilassamento.",
    springsPrestress: "Pretensione",
    springsPrestressMethod: "(un’aggiunta, non presente nei calcoli dell’articolo): lunghezze a riposo accorciate di una frazione, la rete portata in equilibrio con il metodo di Newton e la risposta lineare presa attorno a quello stato, compreso l’irrigidimento per tensione.",
    springsComparison: "Confronto con l’articolo",
    springsFoamHeading: "Schiuma: la transizione auxetica",
    springsFoamComparison: "Il ν direzionale periodico lungo y usa {seeds} semi di {cells} × {cells} celle, passa per zero a η = {cross} e raggiunge {last} a η = 0.5 ({near} a 0.49). L’articolo riporta circa 0.46 e −0.1. Questo confronto tra protocolli diversi rientra in tutte e dieci le barre di errore verso l’alto della Fig. 5 più 0.003 di digitalizzazione; non convalida la striscia. La Fig. 5 riporta dieci realizzazioni; i nostri semi sono una nostra scelta.",
    springsDisorderAxis: "disordine η",
    springsPoissonAxis: "Coefficiente di Poisson ν",
    springsFoamPlot: "Coefficiente di Poisson in funzione del disordine: il nostro e quello dell’articolo",
    springsStripBias: "Il confronto diretto sulla striscia cade fuori dalle barre di errore della Fig. 5 più 0.003 a η = {outside}. La striscia perfetta dà {perfect}; le larghezze 26 e 52 danno 0.354 e 0.345, con estrapolazione a 0.336. È un confronto tra la nostra striscia lineare finita e i marcatori delle simulazioni pubblicate, non una riproduzione della loro geometria o della loro prescrizione al contorno.",
    springsHoneyHeading: "Nido d’ape: Eq. (23)",
    springsHoneyComparison: "Un nido d’ape a lati unitari i cui angoli opposti distano 2ℓ è regolare a ℓ = 1 e rientrante sotto ℓ = ½. L’articolo triangola ogni esagono con un nodo centrale e molle rigide 10⁻³ volte i lati, e confronta con la forma chiusa ν(ℓ) = −(2 − 4ℓ)(ℓ + ½)/(3 + 4ℓ − 4ℓ²). La nostra rete periodica concorda a 3.4 × 10⁻³ con quelle molle e a 3.4 × 10⁻⁶ con molle rigide 10⁻⁶ volte: la differenza è la rigidezza propria delle molle morbide.",
    springsTryHoney: "Mostra ℓ = 0.25 (rientrante)",
    springsHoneyPlot: "Coefficiente di Poisson del nido d’ape: Eq. 23 e la nostra rete",
    springsOrderedHeading: "Reticoli ordinati: un’osservazione sulle costanti elastiche delle molle",
    springsOrderedComparison: "Per i reticoli triangolari ordinati l’articolo dà una forma chiusa, l’Eq. (9) supplementare, per ν in funzione della forma della cella (φ, ψ) e dell’orientamento θ, riportata nella sua Fig. 4. Un reticolo di Bravais non ha spostamenti non affini, quindi la risposta esatta è quella a deformazione uniforme, che calcoliamo in modo indipendente. L’Eq. (9) supplementare e la linea di calcolo della Fig. 7 (modulo di Young del reticolo (3, 2), letto dai dati vettoriali del PDF, moltiplicato per l’area di un triangolo) coincidono con quel risultato affine per costanti elastiche delle molle k",
    springsOrderedConvention: "², sotto 10⁻¹⁴ ed entro 6.1 × 10⁻⁴ rispettivamente. Con costanti elastiche uguali, ν = 1/6 in (φ, ψ, θ) = (1; 0.5; 0), mentre l’Eq. (9) dà 8/27. Il confronto usa quindi la convenzione delle molle con quadrato inverso.",
    springsTryOrdered: "Mostra (1; 0.5)",
    springsTryEqualWeight: "(2; 0.5) a θ = 0.7, peso uguale",
    springsOrientationAxis: "orientamento del reticolo θ, rad",
    springsOrderedPlot: "Coefficiente di Poisson del reticolo ordinato in funzione dell’orientamento",
    springsSelectOrdered: "Seleziona un reticolo ordinato (senza diluizione né pretensione) per tracciare l’Eq. (9) rispetto a entrambe le leggi delle molle.",
    springsUnreproduced: "Non siamo riusciti a riprodurre i punti di simulazione della Fig. 7: l’articolo non dice come la simulazione della striscia misuri il modulo di Young, e la nostra lettura (forza verticale a metà altezza su larghezza e deformazione) non riproduce quei punti.",
    springsRigidityHeading: "Rigidità e connettività (una verifica indipendente)",
    springsRigidity: "Verifica indipendente: cinque campioni a z nominale = 3 hanno G/k < 10⁻⁶; cinque a z = 5.4 hanno G/k ≥ 0.1. Il conteggio di Maxwell dà z = 4 (vedi Jacobs e Thorpe,",
