    springsResult: "Risultato",
    springsLimitations: "Limiti",
    springsNoReference: "Nessun codice di riferimento è pubblico. I confronti poggiano sul testo dell’articolo, sulle sue forme chiuse, sui dati vettoriali delle Figg. 7–9 e su una digitalizzazione della Fig. 5 raster (±0.002).",
