    ferrariEvidenceText: "De lineaire knikbelasting van de productie wordt met het artikel vergeleken. Elke partiële afgeleide van de energie van een verticaal element tot en met de vierde orde wordt met centrale differenties gecontroleerd in drie toestanden. Deze controles valideren afgeleiden van de ligger-energie in productiestijl; ze valideren geen Koiter-coëfficiënten.",
    ferrariMissing: "De berekende resultaten omvatten lineaire knik en één pad met excentrische belasting. De vermelde α en β zijn alleen overgenomen uit het artikel. Optimalisatie, meerdere vormen, grotere samenstellingen en experimentele validatie vallen buiten deze vergelijking.",
    ferrariBlocker: "Een geschaalde lineaire verplaatsing en lineaire knikvorm voldoen in de eerste proefberekening niet aan de niet-lineaire kritieke-puntvergelijkingen. Uit die verworpen berekening worden geen coëfficiënten of Koiter-voorspelling getoond. Eerst moeten de kritieke toestand en de modale normalisatie worden opgelost.",
    ferrariAuthors: "Vragen aan de auteurs",
    ferrariQuestions: "Kunnen jullie de minimale invoer van §2.1.2, het net en de liggerformulering delen; de precieze normalisatie en tekenafspraak van ξ naar hoekrotatie; en de referentiearrays voor α, β en de booglengte? Verduidelijk ook de vermelde foutpercentages van de coëfficiënten, die afwijken van berekeningen met de afgeronde waarden.",
    ferrariReference: "Gepubliceerde referentie",
    ferrariReferenceText: "§2.1.2, pagina 4–5: gesloten vorm (λ₁, α, β) = ({closed}); numeriek ({numerical}). Figuur 2b staat op pagina 4. Dit zijn referentiewaarden, geen berekende coëfficiënten.",
    ferrariReplay: "Vooraf berekende weergave (dezelfde productiesolver)",
