    ferrariCached: "Opgeslagen resultaat uit deze browser",
    ferrariRun: "Live opnieuw berekenen",
    ferrariStop: "Stoppen",
    ferrariRestart: "Weergave herstarten",
    ferrariStep: "Padmonster",
    ferrariFailed: "De live berekening is mislukt. De laatst getoonde gegevens zijn behouden.",
    ferrariPath: "Booglengtepad van de productie",
    ferrariTheta: "Hoekrotatie (rad)",
    ferrariLambda: "Belastingfactor λ",
    ferrariViewer: "Verplaatsing van het Roorda-raamwerk",
    ferrariDisclaimer: "Onderzoek, geen ontwerptool.",
    ferrariComparison: "Elk opgeslagen padmonster wordt gecontroleerd met een native productieberekening. De browsersolver wordt gecontroleerd met de native eindverplaatsing, -rotatie en belastingfactor. Dit is een solverregressie, geen vergelijking met de code van de auteurs of figuur 2b.",
    formPositionError: "Maximale positiefout t.o.v. de referentie",
    formForceError: "Maximale krachtfout t.o.v. de referentie",
    formTitle: "Vier kabels, één evenwicht",
    formLead: "Vind de vorm van het systeem van vier staven in fig. 2 met positieve krachtdichtheden. Wijzig de belasting, bereken opnieuw in Rust en open de gevonden geometrie als vakwerk in Stabileo.",
    formScopeTitle: "Wat wordt gereproduceerd",
    formScope: "Deze eerste versie implementeert het voorwaartse evenwichtsprobleem uit paragraaf 2.1, fig. 2 en vgl. (7). Ons kabelnet van vier kabels heeft één vrije knoop en vier vaste opleggingen. De topologie volgt het artikel; de afmetingen en belastingen zijn hier expliciet gekozen en niet uit de figuur overgenomen. Het artikel ontwikkelt differentieerbaar inverse ontwerp; die bijdrage valt buiten deze versie.",
    formMethodTitle: "De voorwaartse methode",
    formMethod: "Krachtdichtheid is de normaalkracht (trek) gedeeld door de staaflengte. Positieve dichtheden geven een verankerd net een positief-definiete evenwichtsmatrix. De onderzoekscrate stelt deze matrix op en gebruikt de ijle Cholesky-factorisatie van de productie-engine voor de drie coördinaten. De krachten volgen uit f = qℓ.",
    formInputs: "De opleggingen liggen op (±2, ±2, 0) m. De basisbelasting naar beneden is 4 kN en elke dichtheid is 1 kN/m. Vgl. (7) geeft dan z = −1 m, lengte = 3 m en trek = 3 kN. Dit zijn afgeleide doelwaarden voor onze invoer, geen gepubliceerde numerieke waarnemingen.",
    formEvidenceTitle: "Bewijs en toleranties",
    formCheckLabel: "Tegenover jax_fdm (10 controles); hieronder 20 analytische/engine-controles",
    formComparison: "Onze eigen invoer: vergeleken met vgl. (7) en jax_fdm; de numerieke resultaten van het artikel worden niet gereproduceerd.",
    formDensityHint: "Voer 0.5–2 kN/m in.",
    formLoadHint: "Voer 1–8 kN in.",
    researchLanguages: "Onderzoeksinhoud is beschikbaar in het Engels, Spaans, Portugees, Hongaars, Italiaans, vereenvoudigd Chinees en Nederlands. Verdere vertalingen verschillen per benchmark. Bij een ontbrekende vertaling verschijnt de Engelse tekst.",
    formEvidence: "Vijf invoergevallen vergelijken elke coördinaat en kabelkracht met ongewijzigde jax_fdm in float64. De absolute toleranties zijn 1e-12 m voor coördinaten, 1e-12 kN voor referentiekrachten en evenwichtsresiduen en 1e-9 kN voor vakwerkkrachten van de productie. Het validatiebestand legt elke waargenomen fout vast. De weergave is een belastingsreeks die door dezelfde Rust-solver is berekend, geen convergentie-iteraties. De schalen zijn ongeveer 3 m, 3–12 kN en EA = 200000 kN. Het budget van 1e-12 laat afrondingsfouten van float64-assemblage en Cholesky toe; 1e-9 kN laat uitdoving toe bij het terugrekenen van elastische krachten uit kleine verplaatsingen bij deze grote stijfheid.",
    formReference: "Referentie: jax_fdm, MIT, revisie 9a17fd379071fb3511ca914f46e8d1e8c286460e. Het manifest legt de SHA-256 van het bronarchief, de uitvoerhashes en de geïnstalleerde omgeving vast. Deze revisie is niet bevestigd als de publicatierevisie.",
    formEngineTitle: "Wat de productie-engine controleert",
    formEngine: "De editor ontvangt de gevonden geometrie, de vaste opleggingsverplaatsingen en dezelfde verticale belasting als een lineair-elastisch 3D-vakwerk. Bij gelijke staafstijfheden zorgt symmetrie ervoor dat de normaalkrachten overeenkomen met FDM. Tests controleren ook de verticale verplaatsing tegen de elastische gesloten vorm. Dit is een aparte berekening van aanvankelijk spanningsloze staven: kabelvoorspanning en geometrische stijfheid worden niet overgedragen.",
    formLimitsTitle: "Nog niet gereproduceerd",
    formLimits: "Geen adjuncten, gradiënten, optimalisatie, schalen, gemengde trek/druk, vormafhankelijke belasting, knik of tijdsclaims. Er worden geen gepubliceerde geoptimaliseerde vormen of tabelwaarden gereproduceerd. Het voorbeeld is een gelabelde projectie; de editor bevat het volledige ruimtelijke model.",
    formDisclaimer: "Overeenstemming met een andere code is geen experimentele validatie of constructieve certificering.",
    formQuestionsTitle: "Vragen aan de auteurs",
    formQuestions: "Welke commit en omgeving hebben het artikel gegenereerd? Is de exacte invoer van fig. 2 beschikbaar? Welke kleine kabelnet-benchmark en referentiecoördinaten, -krachten en -gradiënten raden jullie aan voor een volgende reproductie van het inverse ontwerp?",
