    springsEqualWeight: "k ∝ 1/ℓ² (zoals vgl. 9)",
    springsCompressionLegend: "druk positief na deling door negatieve ε · strip van links naar rechts samengedrukt, eindrijen vastgehouden",
    springsTensionLegend: "trek positief · strip van links naar rechts getrokken, eindrijen vastgehouden",
    springsZeroLegend: "opgelegde rek nul · eindrijen vastgehouden",
    springsEditorChanged: "Het experiment is gewijzigd terwijl de editor laadde. Probeer opnieuw om het huidige netwerk te laden.",
    springsEditorFailed: "De Stabileo-editor kon niet worden geladen:",

    springsTitle: "Auxetische veernetwerken",
    springsLead: "Trek aan een strip van hookeaanse veren en lees af hoeveel hij smaller wordt. Schud de knopen van het driehoekige rooster en hij wordt juist breder: hij wordt auxetisch. Het netwerk rechts wordt in je browser berekend als vakwerk op de engine van Stabileo, en dezelfde strip opent in de echte Stabileo-editor. Er is geen referentiecode openbaar (“op aanvraag beschikbaar”), dus vergelijken we met de gepubliceerde getallen, gesloten vormen en figuren van het artikel en met exacte resultaten.",
    springsPaperShows: "Wat het artikel laat zien",
    springsOverview: "Veel materialen, van metamateriaalroosters tot celmembranen, worden gemodelleerd als netwerken van hookeaanse veren. Grossman en Boudaoud leiden het elastische continuüm af waarop zo’n netwerk lijkt, alleen met zijn geometrie en topologie, en ze berekenen de",
    springsNonaffine: "niet-affiene",
    springsOverviewRelaxation: "verplaatsingen: de lokale afwijkingen van een uniforme rek die wanordelijke netwerken slapper maken dan de schatting met uniforme rek. Ze toetsen de theorie aan simulaties van een uitgerekte strip voor drie families: geordende driehoekige roosters, een honingraat die re-entrant wordt en een “schuim”, gemaakt door de knopen van een driehoekig rooster willekeurig te verschuiven, dat",
    springsAuxetic: "auxetisch",
    springsOverviewAuxetic: "wordt (negatieve dwarscontractiecoëfficiënt: hij wordt breder als je eraan trekt) naarmate de wanorde toeneemt.",
    springsTry: "Probeer het:",
    springsPerfect: "perfect rooster, η = 0",
    springsTryAuxetic: "η = 0.5, auxetisch",
    springsModel: "Het model dat we oplossen",
    springsSprings: "Veren",
    springsJoin: "verbinden knopen; elke veer heeft stijfheid",
    springsRestLength: ", rustlengte ℓ̄",
    springsCurrentLength: "en huidige lengte ℓ",
    springsEnergy: ", en de energie is",
    springsModelViewer: "(vgl. 3). De viewer toont de normaalkracht op het vervormde vakwerk. We berekenen de volgende responsen.",
    springsStripTest: "Lineaire striptest.",
    springsStripMethod: "Een strip van 13 × 52 met {nodes} knopen, vergeleken met de circa 676 hoekpunten van het artikel (par. V A, p. 9–10). We houden volledige eindrijen vast, gekozen vóór de wanorde, en leggen een verticaal increment ε × 52 op; het artikel zet de bovenste hoekpunten op y = 52(1 + ε). Dit zijn verschillende randvoorwaarden. De breedte wordt gemeten tussen de knopen het dichtst bij halve hoogte. De vakwerksolver van de productie komt overeen tot onder 10⁻¹³ (vastgelegd; tolerantie 10⁻⁸).",
    springsExactModuli: "Exacte effectieve moduli.",
    springsPeriodicMethod: "Een periodieke cel onder een opgelegde macroscopische rek, waarbij elke knoop vrij kan relaxeren: de stijfheid die overblijft is de elasticiteitstensor C van het netwerk, inclusief de niet-affiene verzwakking, zonder randeffecten. De tensor voor uniforme rek (affien) is dezelfde som zonder relaxatie.",
    springsPrestress: "Voorspanning",
    springsPrestressMethod: "(een toevoeging, niet in de berekeningen van het artikel): rustlengtes met een fractie verkort, het netwerk met de methode van Newton tot evenwicht gerelaxeerd, en de lineaire respons genomen rond die toestand, inclusief trekverstijving.",
    springsComparison: "Vergelijking met het artikel",
    springsFoamHeading: "Schuim: de auxetische overgang",
    springsFoamComparison: "De periodieke richtings-ν langs y gebruikt {seeds} seeds van {cells} × {cells} cellen, snijdt nul bij η = {cross} en bereikt {last} bij η = 0.5 ({near} bij 0.49). Het artikel meldt ongeveer 0.46 en −0.1. Deze vergelijking tussen verschillende protocollen valt binnen alle tien de opwaartse foutbalken van fig. 5 plus 0.003 digitalisering; ze valideert de strip niet. Fig. 5 meldt tien realisaties; onze seeds zijn onze eigen keuze.",
    springsDisorderAxis: "wanorde η",
    springsPoissonAxis: "dwarscontractiecoëfficiënt ν",
    springsFoamPlot: "Dwarscontractiecoëfficiënt tegen wanorde: de onze en die van het artikel",
    springsStripBias: "De directe stripvergelijking ligt buiten de foutbalken van fig. 5 plus 0.003 bij η = {outside}. De perfecte strip geeft {perfect}; breedtes 26 en 52 geven 0.354 en 0.345, extrapolerend naar 0.336. Dit is een vergelijking van onze eindige lineaire strip met de gepubliceerde simulatiemarkeringen, geen reproductie van hun geometrie of randvoorwaarden.",
    springsHoneyHeading: "Honingraat: vgl. (23)",
    springsHoneyComparison: "Een honingraat met eenheidsribben waarvan de tegenover elkaar liggende hoeken 2ℓ uit elkaar liggen, is regelmatig bij ℓ = 1 en re-entrant onder ℓ = ½. Het artikel trianguleert elke zeshoek met een middenknoop en veren die 10⁻³ zo stijf zijn als de ribben, en vergelijkt met de gesloten vorm ν(ℓ) = −(2 − 4ℓ)(ℓ + ½)/(3 + 4ℓ − 4ℓ²). Ons periodieke netwerk komt tot 3.4 × 10⁻³ overeen met die veren en tot 3.4 × 10⁻⁶ met veren die 10⁻⁶ zo stijf zijn: het verschil is de eigen stijfheid van de zachte veren.",
    springsTryHoney: "Toon ℓ = 0.25 (re-entrant)",
    springsHoneyPlot: "Dwarscontractiecoëfficiënt van de honingraat: vgl. 23 en ons netwerk",
    springsOrderedHeading: "Geordende roosters: een waarneming over veerconstanten",
    springsOrderedComparison: "Voor geordende driehoekige roosters geeft het artikel een gesloten vorm, vgl. (9) van het aanvullende materiaal, voor ν als functie van de celvorm (φ, ψ) en de oriëntatie θ, getekend in zijn fig. 4. Een Bravais-rooster heeft geen niet-affiene verplaatsingen, dus het exacte antwoord is dat voor uniforme rek, dat we onafhankelijk berekenen. Vgl. (9) van het aanvullende materiaal en de berekeningslijn van fig. 7 (de elasticiteitsmodulus van het (3, 2)-rooster, afgelezen uit de vectorgegevens van de pdf, maal de oppervlakte van één driehoek) vallen samen met dat affiene resultaat voor veerconstanten k",
    springsOrderedConvention: "², respectievelijk onder 10⁻¹⁴ en binnen 6.1 × 10⁻⁴. Met gelijke veerconstanten is ν = 1/6 bij (φ, ψ, θ) = (1, 0.5, 0), terwijl vgl. (9) 8/27 geeft. De vergelijking gebruikt daarom de afspraak van omgekeerd kwadratische veren.",
    springsTryOrdered: "Toon (1, 0.5)",
    springsTryEqualWeight: "(2, 0.5) bij θ = 0.7, gelijk gewicht",
    springsOrientationAxis: "roosteroriëntatie θ, rad",
    springsOrderedPlot: "Dwarscontractiecoëfficiënt van het geordende rooster tegen de oriëntatie",
    springsSelectOrdered: "Selecteer een geordend rooster (zonder verdunning of voorspanning) om vgl. (9) voor beide veerwetten te tekenen.",
    springsUnreproduced: "We konden de simulatiepunten van fig. 7 niet reproduceren: het artikel zegt niet hoe zijn stripsimulatie de elasticiteitsmodulus meet, en onze interpretatie (verticale kracht door halve hoogte gedeeld door breedte en rek) reproduceert die punten niet.",
    springsRigidityHeading: "Stijfheid en connectiviteit (een onafhankelijke controle)",
    springsRigidity: "Onafhankelijke controle: vijf monsters bij nominale z = 3 hebben G/k < 10⁻⁶; vijf bij z = 5.4 hebben G/k ≥ 0.1. Maxwell-telling geeft z = 4 (zie Jacobs en Thorpe,",
    springsTryDilute: "Verdun tot z ≈ 3.7",
