    formScope: "Ez az első változat a 2.1. szakasz, a 2. ábra és a (7) egyenlet közvetlen egyensúlyi feladatát valósítja meg. Négykötelű hálónknak egy szabad csomópontja és négy befogott támasza van. Topológiája a cikket követi; méreteit és terheit itt kifejezetten mi választottuk, nem az ábráról vettük át. A cikk differenciálható inverz tervezést dolgoz ki; ez a hozzájárulás kívül esik ezen a változaton.",
    formMethodTitle: "A közvetlen módszer",
    formMethod: "Az erősűrűség a tengelyirányú húzóerő és a rúdhossz hányadosa. Pozitív sűrűségek mellett egy lehorgonyzott háló egyensúlyi mátrixa pozitív definit. A kutatási crate összeállítja ezt a mátrixot, és a három koordinátához az éles megoldómotor ritka Cholesky-felbontását használja. Az erők az f = qℓ összefüggésből adódnak.",
    formInputs: "A támaszok helye (±2, ±2, 0) m. Az alapeseti lefelé mutató teher 4 kN, és minden sűrűség 1 kN/m. A (7) egyenlet ekkor z = −1 m-t, 3 m hosszt és 3 kN húzóerőt ad. Ezek a mi bemeneteinkből levezetett célértékek, nem közölt numerikus eredmények.",
    formEvidenceTitle: "Bizonyítékok és tűrések",
    formCheckLabel: "A jax_fdm-mel szemben (10 ellenőrzés); alább 20 analitikus/megoldómotor-ellenőrzés",
    formComparison: "Saját bemeneteink: a (7) egyenlettel és a jax_fdm-mel összevetve; a cikk numerikus eredményeit nem reprodukáljuk.",
    formDensityHint: "Adjon meg 0.5–2 kN/m közötti értéket.",
    formLoadHint: "Adjon meg 1–8 kN közötti értéket.",
    researchLanguages: "A kutatási tartalom angol, spanyol, portugál, magyar, olasz, egyszerűsített kínai és holland nyelven érhető el. A további fordítások példánként eltérnek. Ha nincs fordítás, az angol szöveg jelenik meg.",
    formEvidence: "Öt bemeneti eset minden koordinátát és kötélerőt összevet a módosítatlan jax_fdm float64-es eredményeivel. Az abszolút tűrés a koordinátákra 1e-12 m, a referenciaerőkre és az egyensúlyi reziduumokra 1e-12 kN, az éles rácsos tartó erőire 1e-9 kN. A validációs fájl minden megfigyelt hibát rögzít. A visszajátszás ugyanazzal a Rust-megoldóval számított teherléptetés, nem konvergencia-iterációk sora. A nagyságrendek körülbelül 3 m, 3–12 kN és EA = 200000 kN. Az 1e-12-es keret a float64-es összeállítás és a Cholesky-felbontás kerekítési hibáit fogadja be; az 1e-9 kN a rugalmas erők kis elmozdulásokból való visszaszámításakor fellépő kioltást engedi meg ennél a nagy merevségnél.",
    formReference: "Referencia: jax_fdm, MIT, 9a17fd379071fb3511ca914f46e8d1e8c286460e revízió. A manifest rögzíti a forrásarchívum SHA-256 értékét, a kimenetek hash-eit és a telepített környezetet. Nem erősítették meg, hogy ez a publikációhoz használt revízió.",
    formEngineTitle: "Mit ellenőriz az éles megoldómotor",
    formEngine: "A szerkesztő a kapott geometriát, a rögzített támaszeltolódásokat és ugyanazt a függőleges terhet 3D lineárisan rugalmas rácsos tartóként kapja meg. Egyenlő rúdmerevségek mellett a szimmetria miatt a normálerők megegyeznek az FDM-mel. A tesztek a függőleges elmozdulását a rugalmas zárt alakú megoldással is ellenőrzik. Ez kezdetben feszültségmentes rudak külön számítása: a kötelek előfeszítése és a geometriai merevség nem kerül át.",
    formLimitsTitle: "Még nem reprodukált",
    formLimits: "Nincsenek adjungáltak, gradiensek, optimalizálás, héjak, vegyes húzás/nyomás, alakfüggő terhelés, kihajlás vagy futásidőre vonatkozó állítások. Közölt optimalizált alakokat vagy táblázati értékeket nem reprodukálunk. Az előnézet feliratozott vetület; a szerkesztő a teljes térbeli modellt tartalmazza.",
    formDisclaimer: "Egy másik kóddal való egyezés nem kísérleti validálás és nem mérnöki tanúsítás.",
    formQuestionsTitle: "Kérdések a szerzőkhöz",
    formQuestions: "Melyik commit és környezet állította elő a cikk eredményeit? Elérhetők a 2. ábra pontos bemenetei? Melyik kis kötélháló-referenciafeladatot, referenciakoordinátákat, erőket és gradienseket ajánlanák egy későbbi inverztervezési reprodukcióhoz?",
