    springsTitle: "Auxetikus rugóhálózatok",
    springsLead: "Húzzon meg egy Hooke-rugókból álló sávot, és nézze meg, mennyire keskenyedik. Rázza meg a háromszögrács csomópontjait, és a sáv ehelyett szélesedni kezd: auxetikussá válik. A jobb oldali hálót a böngészője rácsos tartóként oldja meg a Stabileo megoldómotorjával, és ugyanez a sáv a valódi Stabileo-szerkesztőben is megnyílik. Referenciakód nem nyilvános („kérésre elérhető”), ezért a cikkben közölt számokkal, zárt alakú megoldásokkal és ábrákkal, valamint egzakt eredményekkel vetjük össze.",
    springsPaperShows: "Mit mutat a cikk",
    springsOverview: "Számos anyagot, a metaanyag-rácsoktól a sejtmembránokig, Hooke-rugók hálózataként modelleznek. Grossman és Boudaoud csak a geometria és a topológia alapján levezeti azt a rugalmas kontinuumot, amelyként egy ilyen háló viselkedik, és kiszámítják a",
    springsNonaffine: "nemaffin",
    springsOverviewRelaxation: "elmozdulásokat: az egyenletes nyújtástól való helyi eltéréseket, amelyek miatt a rendezetlen hálók lágyabbak az egyenletes alakváltozásra adott becslésnél. Az elméletet egy nyújtott sáv szimulációival ellenőrzik három családra: rendezett háromszögrácsokra, egy befelé hajló (re-entrant) cellájúvá váló méhsejtrácsra, és egy háromszögrács csomópontjainak véletlenszerű elmozdításával létrehozott „habra”, amely a rendezetlenség növekedtével",
    springsAuxetic: "auxetikussá",
    springsOverviewAuxetic: "válik (negatív Poisson-tényező: húzásra szélesedik).",
    springsTry: "Próbálja ki:",
    springsPerfect: "tökéletes rács, η = 0",
    springsTryAuxetic: "η = 0.5, auxetikus",
    springsModel: "A megoldott modell",
    springsSprings: "Rugók",
    springsJoin: "kötik össze a csomópontokat; mindegyik merevsége",
    springsRestLength: ", nyugalmi hossza ℓ̄",
    springsCurrentLength: "és pillanatnyi hossza ℓ",
    springsEnergy: ", az energia pedig",
    springsModelViewer: "(3. egyenlet). A megjelenítő a deformált rácsos tartó normálerőit mutatja. A következő válaszokat számítjuk.",
    springsStripTest: "Lineáris sávkísérlet.",
    springsStripMethod: "Egy 13 × 52-es sáv {nodes} csomóponttal, szemben a cikk nagyjából 676 csúcspontjával (V. A szakasz, 9–10. o.). A rendezetlenség előtt kiválasztott teljes szélső sorokat rögzítjük, és ε × 52 függőleges növekményt írunk elő; a cikk a felső csúcspontokat y = 52(1 + ε) helyzetbe állítja. Ezek eltérő peremfeltételek. A szélességet a félmagassághoz legközelebbi csomópontok között mérjük. Az éles rácsostartó-megoldó 10⁻¹³ alatti eltéréssel egyezik (rögzítve; tűrés 10⁻⁸).",
    springsExactModuli: "Egzakt effektív modulusok.",
    springsPeriodicMethod: "Periodikus cella előírt makroszkopikus alakváltozással, minden csomópont szabadon relaxálhat: a megmaradó merevség a háló C rugalmassági tenzora, a nemaffin lágyulással együtt, peremhatások nélkül. Az egyenletes alakváltozású (affin) tenzor ugyanez az összeg relaxáció nélkül.",
    springsPrestress: "Előfeszítés",
    springsPrestressMethod: "(kiegészítés, a cikk számításaiban nem szerepel): a nyugalmi hosszakat egy hányaddal lerövidítjük, a hálót Newton-módszerrel egyensúlyba relaxáljuk, és a lineáris választ e körül az állapot körül vesszük, a húzásból adódó merevedéssel együtt.",
    springsComparison: "Összehasonlítás a cikkel",
    springsFoamHeading: "Hab: az auxetikus átmenet",
    springsFoamComparison: "Az y irányú periodikus irányfüggő ν {seeds} véletlen maggal, {cells} × {cells} cellán számolva η = {cross} értéknél metszi a nullát, és η = 0.5-nél {last} értéket ér el (0.49-nél {near}). A cikk körülbelül 0.46-ot és −0.1-et közöl. Ez az eltérő protokollok közötti összehasonlítás mind a tíz felfelé mutató 5. ábrabeli hibasáv plusz 0.003 digitalizálási eltérés határain belül marad; a sávot nem validálja. Az 5. ábra tíz realizációt közöl; a mi véletlen magjaink saját választásunk.",
    springsDisorderAxis: "η rendezetlenség",
    springsPoissonAxis: "ν Poisson-tényező",
    springsFoamPlot: "Poisson-tényező a rendezetlenség függvényében: a miénk és a cikké",
    springsStripBias: "A közvetlen sávos összehasonlítás η = {outside} értéknél kívül esik az 5. ábra hibasávjain plusz 0.003-on. A tökéletes sáv értéke {perfect}; 26 és 52 szélességnél 0.354 és 0.345 adódik, ami 0.336-ra extrapolál. Ez véges lineáris sávunk összehasonlítása a közölt szimulációs jelölőkkel, nem a geometriájuk vagy a peremfeltételeik reprodukciója.",
    springsHoneyHeading: "Méhsejtrács: a (23) egyenlet",
    springsHoneyComparison: "Az egységnyi élű méhsejtrács, amelynek szemközti sarkai 2ℓ távolságra vannak, ℓ = 1-nél szabályos, ℓ = ½ alatt pedig befelé hajló. A cikk minden hatszöget egy középső csomóponttal és az élek merevségének 10⁻³-szeresét kitevő rugókkal háromszögel, és a ν(ℓ) = −(2 − 4ℓ)(ℓ + ½)/(3 + 4ℓ − 4ℓ²) zárt alakkal veti össze. Periodikus hálónk ezekkel a rugókkal 3.4 × 10⁻³-on belül egyezik, és 3.4 × 10⁻⁶-on belül, ha a rugók merevsége csak 10⁻⁶-szoros: a különbség a lágy rugók saját merevsége.",
    springsTryHoney: "ℓ = 0.25 megjelenítése (befelé hajló)",
    springsHoneyPlot: "A méhsejtrács Poisson-tényezője: a (23) egyenlet és a hálónk",
    springsOrderedHeading: "Rendezett rácsok: megfigyelés a rugóállandókról",
    springsOrderedComparison: "Rendezett háromszögrácsokra a cikk zárt alakot ad, a Kiegészítő anyag (9) egyenletét, ν-re a cella alakjának (φ, ψ) és a θ orientációnak a függvényében, amelyet a 4. ábrán ábrázol. Egy Bravais-rácsban nincsenek nemaffin elmozdulások, így az egzakt válasz az egyenletes alakváltozású megoldás, amelyet függetlenül számítunk. A Kiegészítő anyag (9) egyenlete és a 7. ábra számított görbéje (a (3, 2) rács Young-modulusa, a PDF vektoradataiból kiolvasva, egy háromszög területével szorozva) a k",
    springsOrderedConvention: "² rugóállandókkal egyezik ezzel az affin eredménnyel, rendre 10⁻¹⁴ alatt és 6.1 × 10⁻⁴-en belül. Egyenlő rugóállandókkal ν = 1/6, ha (φ, ψ, θ) = (1, 0.5, 0), míg a (9) egyenlet 8/27-et ad. Az összehasonlítás ezért az inverz négyzetes rugókonvenciót használja.",
    springsTryOrdered: "(1, 0.5) megjelenítése",
