    springsSelectOrdered: "Válasszon rendezett rácsot (ritkítás és előfeszítés nélkül), hogy a (9) egyenletet mindkét rugótörvénnyel összevesse.",
    springsUnreproduced: "A 7. ábra szimulációs pontjait nem tudtuk reprodukálni: a cikk nem írja le, hogyan méri a sávszimuláció a Young-modulust, és a mi értelmezésünk (a félmagasságon átmenő függőleges erő osztva a szélességgel és az alakváltozással) nem adja vissza ezeket a pontokat.",
